@startuml

class City {
  + Name : string
}

class H2SLocation {
  + LocationID : int
}

class Resident {
  + Name : string
  + StreetAddress : string
  + PhoneNumber : string
  + Email : string
}

class PickupRequest {
  + RequestID : int
  + ItemDescription : string
  + RequestedDate : date
  + RequestedTime : time
}

class Vehicle {
  + LicensePlate : string
  + StorageCapacity : float
}

class VolunteerDriver {
  + Name : string
  + AvailableDays : string[]
}

class PickupRoute {
  + RouteID : int
  + Date : date
}

class Article {
  + RFIDTag : string
  + Description : string
  + Category : string
}

class Category {
  + CategoryName : string
}

class DistributionCenter {
  + Address : string
}

class Client {
  + Name : string
  + HomeAddress : string
}

class Employee {
  + EmployeeID : int
  + Name : string
}

class FoodBank {
  + Address : string
}

H2SLocation "1" -- "1" City
H2SLocation "1" -- "1" DistributionCenter

Resident "1" -- "*" PickupRequest
PickupRequest "1" -- "1" Vehicle
PickupRequest "1" -- "1" VolunteerDriver

Vehicle "1" -- "*" PickupRoute
VolunteerDriver "1" -- "*" PickupRoute

PickupRoute "1" -- "*" PickupRequest

Article "*" -- "1" DistributionCenter
Article "*" -- "1" Category

DistributionCenter "1" -- "*" Employee
DistributionCenter "1" -- "*" Client

Client "*" -- "*" Article : requests
Employee "1" -- "*" Client : calls
Employee "1" -- "*" Article : inspects

DistributionCenter "1" -- "1" FoodBank
Resident "1" -- "*" Article : provides
Article "*" -- "1" Resident : belongsTo

@enduml

